<template>
  <section class="matrix-page">
    <div class="matrix-heading"><div><span>桥型专属配置</span><h2>{{ mode==='components'?'桥型-部位-部件矩阵':'桥型-初检项目矩阵' }}</h2></div><el-button v-if="selectedType" @click="router.push(rootPath)"><ArrowLeft :size="16"/>返回桥型总览</el-button></div>
    <div v-if="!selectedType" class="type-cards"><button v-for="(item,index) in bridgeTypes" :key="item.bridge_type_code" :class="`theme-${index%6}`" @click="openType(item)"><span>{{ String(index+1).padStart(2,'0') }}</span><b>{{ item.bridge_type_name }}</b><small>{{ countFor(item.bridge_type_code) }} 条配置</small><ChevronRight :size="20"/></button></div>
    <template v-else>
      <section class="type-banner"><div><span>{{ selectedType.bridge_type_code }}</span><h3>{{ selectedType.bridge_type_name }}</h3></div><strong>{{ rows.length }} 条配置</strong></section>
      <div v-if="mode==='components'" class="part-layout"><nav><button v-for="group in groupedRows" :key="group.name" :class="{active:activeGroup===group.name}" @click="activeGroup=group.name"><span>{{ group.name }}</span><b>{{ group.rows.length }}</b></button></nav><section class="part-detail"><div class="part-title"><div><span>部位</span><h3>{{ currentGroup?.name }}</h3></div><el-tag>{{ currentGroup?.rows.length||0 }} 个部件</el-tag></div><div class="component-list"><article v-for="row in currentGroup?.rows||[]" :key="row.config_id"><div class="component-index">{{ row.display_order }}</div><div><b>{{ row.component_name }}</b><span>{{ row.component_code }}</span></div></article></div></section></div>
      <div v-else class="initial-groups"><section v-for="group in groupedRows" :key="group.name"><div class="part-title"><div><span>项目分类</span><h3>{{ group.name }}</h3></div><el-tag>{{ group.rows.length }} 项</el-tag></div><el-table :data="group.rows" border><el-table-column prop="item_code" label="项目编码" width="110"/><el-table-column prop="item_name" label="初检项目" min-width="220"/><el-table-column prop="requirement_type" label="检查要求" width="120"><template #default="{row}"><el-tag :type="row.requirement_type==='required'?'danger':'warning'">{{ row.requirement_type==='required'?'必检':'条件触发' }}</el-tag></template></el-table-column><el-table-column prop="trigger_condition" label="触发条件" min-width="240"/><el-table-column prop="display_order" label="顺序" width="80"/></el-table></section></div>
    </template>
    <section v-if="!selectedType" class="relation-table"><div class="table-title"><div><span>原始关系表</span><h3>全部矩阵关系</h3></div><el-tag>{{ allRows.length }} 条关系</el-tag></div><el-table :data="allRows" border height="500"><el-table-column prop="bridge_type_name" label="桥梁类型" min-width="190"/><el-table-column v-if="mode==='components'" prop="part_name" label="部位" width="130"/><el-table-column v-if="mode==='components'" prop="component_name" label="部件" min-width="180"/><el-table-column v-if="mode==='initial-items'" prop="item_code" label="项目编码" width="110"/><el-table-column v-if="mode==='initial-items'" prop="item_name" label="初检项目" min-width="220"/><el-table-column v-if="mode==='initial-items'" prop="requirement_type" label="要求" width="110"><template #default="{row}">{{ row.requirement_type==='required'?'必检':'条件触发' }}</template></el-table-column><el-table-column v-if="mode==='initial-items'" prop="trigger_condition" label="触发条件" min-width="240"/><el-table-column prop="display_order" label="顺序" width="80"/></el-table></section>
  </section>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, ChevronRight } from 'lucide-vue-next'
import http from '../api/http'
const props=defineProps({mode:{type:String,default:'components'}}),route=useRoute(),router=useRouter(),bridgeTypes=ref([]),allRows=ref([]),rows=ref([]),activeGroup=ref('')
const selectedCode=computed(()=>String(route.params.bridgeTypeCode||'')),selectedType=computed(()=>bridgeTypes.value.find(x=>x.bridge_type_code===selectedCode.value)),rootPath=computed(()=>props.mode==='components'?'/base/component-matrix':'/base/initial-matrix')
const groupedRows=computed(()=>{const map=new Map();for(const row of rows.value){const name=props.mode==='components'?(row.part_name||'其他'):(row.item_category||'其他项目');if(!map.has(name))map.set(name,[]);map.get(name).push(row)}return[...map].map(([name,items])=>({name,rows:items}))}),currentGroup=computed(()=>groupedRows.value.find(x=>x.name===activeGroup.value)||groupedRows.value[0])
async function load(){const page=await http.get('/bridge-types',{params:{size:100}});bridgeTypes.value=page.records;allRows.value=await http.get(`/matrices/${props.mode}`);rows.value=selectedCode.value?allRows.value.filter(x=>x.bridge_type_code===selectedCode.value):[];activeGroup.value=groupedRows.value[0]?.name||''}
function openType(item){router.push(`${rootPath.value}/${item.bridge_type_code}`)}function countFor(code){return allRows.value.filter(x=>x.bridge_type_code===code).length}
onMounted(load);watch([()=>props.mode,selectedCode],load)
</script>
<style scoped>
