{display:flex;justify-content:space-between;width:100%;padding:12px;border:0;background:transparent;cursor:pointer;text-align:left}.part-layout nav button.active{background:#0f766e;color:#fff}.part-layout nav b{font-size:11px}.part-detail{padding:20px}.component-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:16px}.component-list article{display:flex;align-items:center;gap:12px;border:1px solid #dbe3ec;padding:13px}.component-index{width:34px;height:34px;display:grid;place-items:center;background:#ecfdf5;color:#0f766e;font-weight:800}.component-list b,.component-list span{display:block}.component-list span{font-size:11px;color:#64748b;margin-top:3px}.initial-groups{display:grid;gap:14px;margin-top:14px}.initial-groups>section{padding:16px}.initial-groups .part-title{margin-bottom:12px}@media(max-width:1000px){.type-cards{grid-template-columns:repeat(2,1fr)}.component-list{grid-template-columns:repeat(2,1fr)}}@media(max-width:680px){.type-cards{grid-template-columns:1fr}.part-layout{grid-template-columns:1fr}.part-layout nav{display:flex;overflow:auto;border-right:0;border-bottom:1px solid #dbe3ec}.part-layout nav button{min-width:130px}.component-list{grid-template-columns:1fr}}
</style>
